function LP([int]$px, [int]$py) { return [IntPtr](($py -shl 16) -bor ($px -band 0xFFFF)) }

$fg = [W]::GetForegroundWindow()
$fgPid = 0
[void][W]::GetWindowThreadProcessId($fg, [ref]$fgPid)

