  }
  "place" {
    # NOACTIVATE(0x0010) | NOSIZE? no: we set size. NOZORDER(0x0004) | SHOWWINDOW(0x0040)
    [void][W]::SetWindowPos($hwnd, [IntPtr]::Zero, $x, $y, $w, $h, 0x0010 -bor 0x0040)
    Start-Sleep -Milliseconds 400
    $r2 = New-Object W+RECT
    [void][W]::GetClientRect($hwnd, [ref]$r2)
    $o2 = New-Object W+POINT
    [void][W]::ClientToScreen($hwnd, [ref]$o2)
    Write-Output "placed origin=$($o2.X),$($o2.Y) client=$($r2.R)x$($r2.B)"
  }
  "click" {
    $px = $x * $scale; $py = $y * $scale
    [void][W]::PostMessage($hwnd, 0x0200, [IntPtr]::Zero, (LP $px $py))
    Start-Sleep -Milliseconds 120
    [void][W]::PostMessage($hwnd, 0x0201, [IntPtr]1, (LP $px $py))
    Start-Sleep -Milliseconds 120
    [void][W]::PostMessage($hwnd, 0x0202, [IntPtr]::Zero, (LP $px $py))
    Write-Output "posted click gui=$x,$y px=$px,$py"
  }
  "scroll" {
    # WM_MOUSEWHEEL: lParam is in screen coords, wParam high word = delta
    $px = $origin.X + ($x * $scale); $py = $origin.Y + ($y * $scale)
    $delta = if ($text -eq "up") { 120 } else { -120 }
    $wp = [IntPtr](($delta -shl 16) -band 0xFFFF0000)
    for ($i = 0; $i -lt 2; $i++) {
      [void][W]::PostMessage($hwnd, 0x020A, $wp, (LP $px $py))
      Start-Sleep -Milliseconds 150
    }
    Write-Output "posted scroll $text at gui=$x,$y"
  }
  "key" {
    $vk = [int]$text
    [void][W]::PostMessage($hwnd, 0x0100, [IntPtr]$vk, [IntPtr]1)
    Start-Sleep -Milliseconds 80
    [void][W]::PostMessage($hwnd, 0x0101, [IntPtr]$vk, [IntPtr]1)
    Write-Output "posted key vk=$vk"
  }
  "type" {
    foreach ($c in $text.ToCharArray()) {
      [void][W]::PostMessage($hwnd, 0x0102, [IntPtr][int]$c, [IntPtr]1)
      Start-Sleep -Milliseconds 40
    }
    Write-Output "typed"
  }
  "shot" {
    $before = @{}
    if (Test-Path $shotDir) { Get-ChildItem $shotDir -File | ForEach-Object { $before[$_.Name] = $true } }
    [void][W]::PostMessage($hwnd, 0x0100, [IntPtr]0x71, [IntPtr]1)
    Start-Sleep -Milliseconds 80
    [void][W]::PostMessage($hwnd, 0x0101, [IntPtr]0x71, [IntPtr]1)
    Start-Sleep -Milliseconds $waitMs
    $new = Get-ChildItem $shotDir -File -ErrorAction SilentlyContinue | Where-Object { -not $before.ContainsKey($_.Name) } |
      Sort-Object LastWriteTime | Select-Object -Last 1
    if (-not $new) { Write-Output "NO_SHOT"; exit 1 }
    Copy-Item $new.FullName $path -Force
    Write-Output "shot=$path from=$($new.Name)"
  }
}
