{"kind":"tool","id":"c2AgRacIHck","toolName":"write_file","input":{"path":"/tmp/verify/Verify.java","instructions":"Headless harness that drives the real cache code and asserts the two behaviors.","content":"import piboh.cleanmc.mod.clean.CacheAutoDetector;
import piboh.cleanmc.mod.clean.CacheCleaner;
import piboh.cleanmc.mod.clean.CacheTarget;
import piboh.cleanmc.mod.clean.CleanReport;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

public final class Verify {

    private static int checks;

    public static void main(String[] args) throws IOException {
        Path root = Files.createTempDirectory("cleanmcmod-verify");

        // Deep mod caches: config/<mod>/cache and config/<mod>/a/b/c/cache
        write(root.resolve("config/modone/cache/a.bin"), 100);
        write(root.resolve("config/modone/cache/nested/b.bin"), 50);
        write(root.resolve("config/modtwo/deep/er/deepest/cache/c.bin"), 70);
        // User data that must never be touched
        write(root.resolve("saves/world/level.dat"), 11);
        write(root.resolve("resourcepacks/pack.zip"), 12);
        write(root.resolve("mods/somemod.jar"), 13);
        write(root.resolve("config/modone/settings.json"), 14);

        List<CacheTarget> detected = new CacheAutoDetector().detect(root);
        System.out.println("detected targets:");
        detected.forEach(t -> System.out.println("  " + t.id() + " -> " + root.relativize(t.path())));

        check("depth: config/modone/cache found",
                detected.stream().anyMatch(t -> t.path().endsWith(Path.of("config/modone/cache"))));
        check("depth: config/modtwo/deep/er/deepest/cache found",
                detected.stream().anyMatch(t -> t.path().endsWith(Path.of("config/modtwo/deep/er/deepest/cache"))));
        check("user data: no target inside saves/",
                detected.stream().noneMatch(t -> root.relativize(t.path()).startsWith("saves")));
        check("user data: no target inside resourcepacks/",
                detected.stream().noneMatch(t -> root.relativize(t.path()).startsWith("resourcepacks")));
        check("user data: no target inside mods/",
                detected.stream().noneMatch(t -> root.relativize(t.path()).startsWith("mods")));

        long cacheFiles = 3;

        // Dry run: nothing deleted, but everything planned and reported.
        CleanReport dry = new CacheCleaner(root).clean(detected, true);
        System.out.println("dry run summary: " + dry.summary());
        dry.results().forEach(r -> System.out.println("  " + r.describe()));
        check("dry run: filesDeleted() == 0", dry.filesDeleted() == 0);
        check("dry run: bytesFreed() == 0", dry.bytesFreed() == 0L);
        check("dry run: filesPlanned() == 3", dry.filesPlanned() == cacheFiles);
        check("dry run: bytes on disk untouched", Files.exists(root.resolve("config/modone/cache/a.bin"))
                && Files.exists(root.resolve("config/modtwo/deep/er/deepest/cache/c.bin")));

        // Real run: same targets, files actually gone, user data intact.
        CleanReport real = new CacheCleaner(root).clean(detected, false);
        System.out.println("real run summary: " + real.summary());
        check("real run: filesDeleted() == 3", real.filesDeleted() == cacheFiles);
        check("real run: filesPlanned() == 0 after clean", real.filesPlanned() == 0);
        check("real run: cache files gone", !Files.exists(root.resolve("config/modone/cache/a.bin"))
                && !Files.exists(root.resolve("config/modtwo/deep/er/deepest/cache/c.bin")));
        check("real run: settings.json survived", Files.exists(root.resolve("config/modone/settings.json")));
        check("real run: saves survived", Files.exists(root.resolve("saves/world/level.dat")));
        check("real run: mods survived", Files.exists(root.resolve("mods/somemod.jar")));

        System.out.println(checks + " checks passed");
    }

    private static void write(Path file, int bytes) throws IOException {
        Files.createDirectories(file.getParent());
        Files.write(file, new byte[bytes]);
    }

    private static void check(String name, boolean ok) {
        if (!ok) {
            System.out.println("FAILED: " + name);
            System.exit(1);
        }
        checks++;
        System.out.println("ok: " + name);
    }
}
