private List<ModVersion> resolveMissing(ModUpdate update, List<LocalMod> installed, List<ModVersion> already)
        throws IOException, InterruptedException {
    List<ModVersion> plan = new ArrayList<>();
    for (String projectId : update.verdict().missing()) {
        ModVersion version = resolver.resolve(projectId);
        if (version == null) return null;
        plan.add(version);
        // one level only: a dependency of a dependency is resolved too, never further.
        for (Dependency dependency : version.dependencies()) {
            if (!dependency.required() || Compatibility.platformProvided(dependency.projectId())) continue;
            if (dependency.projectId().equals(update.candidate().projectId())) continue;
            if (containsProject(plan, already, dependency.projectId())) continue;
            ModVersion nested = resolver.resolve(dependency.projectId());
            if (nested == null) return null;
            plan.add(nested);
        }
    }
    // don't re-download a jar we already have
    plan.removeIf(v -> installed.stream().anyMatch(m -> m.sha1().equalsIgnoreCase(v.sha1())));
    return plan;
}
