        long end = System.currentTimeMillis() + 180000;
        while (System.currentTimeMillis() < end) {
            ModUpdaterService.Snapshot s = svc.snapshot();
            if (s.state() == ModUpdaterService.State.READY || s.state() == ModUpdaterService.State.FAILED) return s;
            Thread.sleep(100);
        }
        throw new IllegalStateException("timeout " + svc.snapshot().state());
    }

